package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaGradeSevenAddSubTest {
 @Test public void indexedDomainIncludesZeroIdentityAndOneMillion(){int max=1000000;assertEquals(500001500001L,BoundedWholeAddSub.count(max));assertArrayEquals(new int[]{0,0},BoundedWholeAddSub.at(max,0));assertArrayEquals(new int[]{max,max},BoundedWholeAddSub.at(max,BoundedWholeAddSub.count(max)-1));for(String id:List.of("add1000","sub1000"))for(int[] v:new int[][]{{0,0},{max,0},{max,max},{max,999999}}){Question q=BoundedWholeAddSub.make(id,v[0],v[1]);q.answers=new String[]{"poison"};q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of(""+(id.equals("add1000")?v[0]:v[0]-v[1]))).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());}}
 @Test public void normalGradeSevenUsesFullRangeWithoutChangingGradeSix(){for(String id:List.of("add1000","sub1000")){var l=GlobalCurriculum.limits("na-nied-primary-2024-v1",id,7);assertTrue(BoundedWholeAddSub.selected(id,l));assertFalse(BoundedWholeAddSub.selected(id,GlobalCurriculum.limits("na-nied-primary-2024-v1",id,6)));Generator g=new Generator(new Random(306));List<String>recent=new ArrayList<>();for(int i=0;i<200;i++){Question q=g.next(id,recent,false,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertTrue(l.allows(q));assertFalse(HelpPlan.forQuestion(q).canTransfer());}}}
}
